using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using System.Drawing;
using System.Windows.Forms;
using System.Web.Script.Serialization;
using System.Diagnostics;
using System.ComponentModel;
using System.Text;
using System.Threading.Tasks;

class SlotChoice {public string code,name;public override string ToString(){return name;}}
class PresetChoice {public string file,title;public override string ToString(){return title;}}
class ArtifactSubLine {
    public ComboBox type,tier;public NumericUpDown count,target;public Label value;public Button match;
    public ArtifactSub stat;public int[] mixed;public bool changing;
}

class ArtifactDesigner : UserControl {
    readonly string root;readonly ArtifactCatalog catalog;readonly JavaScriptSerializer json=new JavaScriptSerializer(){MaxJsonLength=30000000};
    ComboBox sets,slots,stars,initial,main,mode,presets;TextBox search,preview,presetName;NumericUpDown level,quantity;
    Label effect,mainValue,note;Button generate,copy,save,load;List<ArtifactSubLine> lines=new List<ArtifactSubLine>();
    ArtifactPiece piece;ArtifactRequest current;bool updating,busy,externalBusy;
    public event Action<bool> BusyChanged;
    public event Action RequestChanged;
    public ArtifactRequest CurrentRequest {get{return current;}}
    public List<ArtifactMain> AvailableMains {get{return piece==null?new List<ArtifactMain>():piece.mains;}}
    public string CurrentMainProp {get{return (main.SelectedItem as ArtifactMain)==null?null:((ArtifactMain)main.SelectedItem).prop;}}
    public void ChooseMain(string prop){main.SelectedItem=AvailableMains.First(x=>x.prop==prop);}
    public bool IsBusy {get{return busy;}}
    public void SetExternalBusy(bool value){externalBusy=value;UpdatePreview();}
    public ArtifactDesigner(string installationRoot):this(installationRoot,false){}
    public ArtifactDesigner(string installationRoot,bool embedded):this(installationRoot,embedded,null){}
    public ArtifactDesigner(string installationRoot,bool embedded,ArtifactCatalog loaded) {
        root=installationRoot;catalog=loaded??ArtifactMath.Load(root);Dock=DockStyle.Fill;
        var body=new FlowLayoutPanel(){Dock=DockStyle.Fill,AutoScroll=true,FlowDirection=FlowDirection.TopDown,WrapContents=false,Padding=new Padding(12,10,8,6)};
        var select=Row(45);select.Controls.Add(Caption("套装搜索"));search=new TextBox(){Width=165};select.Controls.Add(search);select.Controls.Add(Caption("套装"));sets=Combo(350);select.Controls.Add(sets);
        select.Controls.Add(new Label(){Text="只新增圣遗物，不覆盖已有装备",AutoSize=true,Margin=new Padding(12,5,0,0)});body.Controls.Add(select);
        effect=new Label(){Width=1120,Height=58,AutoEllipsis=true,ForeColor=Color.DimGray};body.Controls.Add(effect);
        var options=Row(45);slots=Combo(140);stars=Combo(65);initial=Combo(65);level=Number(0,20,20,65);quantity=Number(1,5,1,65);mode=Combo(165);mode.Items.AddRange(new object[]{"标准范围","自由测试（超规格）"});mode.SelectedIndex=0;
        options.Controls.Add(Caption("部位"));options.Controls.Add(slots);options.Controls.Add(Caption("星级"));options.Controls.Add(stars);options.Controls.Add(Caption("初始条数"));options.Controls.Add(initial);
        options.Controls.Add(Caption("等级＋"));options.Controls.Add(level);options.Controls.Add(Caption("数量"));options.Controls.Add(quantity);options.Controls.Add(mode);body.Controls.Add(options);
        var mainRow=Row(45);mainRow.Controls.Add(Caption("主词条"));main=Combo(220);mainRow.Controls.Add(main);mainValue=new Label(){Width=150,Height=30,Margin=new Padding(12,4,0,0),ForeColor=Color.DarkBlue};mainRow.Controls.Add(mainValue);
        mainRow.Controls.Add(new Label(){Text="主词条数值按星级和等级计算；副词条不与主词条重复。",AutoSize=true,Margin=new Padding(0,5,0,0)});body.Controls.Add(mainRow);
        body.Controls.Add(new Label(){Text="副词条：贡献次数包含初始那次；目标数值按固定次数匹配最接近的游戏档位组合。百分比直接填11.7，不填0.117。",Width=1120,Height=28});
        for(int i=0;i<4;i++) {
            var line=new ArtifactSubLine();var row=Row(49);row.Controls.Add(Caption("副词条"+(i+1)));line.type=Combo(155);line.tier=Combo(128);line.tier.Items.AddRange(new object[]{"最低档","第二档","第三档","最高档","混合档（目标匹配）"});line.tier.SelectedIndex=3;
            line.count=Number(0,200,1,65);line.target=Number(0,100000,0,100);line.target.DecimalPlaces=2;line.target.Increment=0.1M;
            line.value=new Label(){Width=117,Height=35,ForeColor=Color.DarkBlue,Margin=new Padding(7,4,0,0)};line.match=new Button(){Text="匹配目标",Width=105,Height=34};
            row.Controls.Add(line.type);row.Controls.Add(Caption("档位"));row.Controls.Add(line.tier);row.Controls.Add(Caption("贡献次数"));row.Controls.Add(line.count);row.Controls.Add(line.value);row.Controls.Add(Caption("目标值"));row.Controls.Add(line.target);row.Controls.Add(line.match);body.Controls.Add(row);lines.Add(line);
            line.type.SelectedIndexChanged+=delegate{if(updating||line.changing)return;line.mixed=null;line.stat=line.type.SelectedItem as ArtifactSub;if(line.stat==null)line.count.Value=0;else if(line.count.Value==0)line.count.Value=1;if(line.tier.SelectedIndex==4)line.tier.SelectedIndex=3;UpdatePreview();};
            line.tier.SelectedIndexChanged+=delegate{if(updating||line.changing)return;if(line.tier.SelectedIndex!=4)line.mixed=null;UpdatePreview();};
            line.count.ValueChanged+=delegate{if(updating||line.changing)return;line.mixed=null;if(line.tier.SelectedIndex==4)line.tier.SelectedIndex=3;UpdatePreview();};
            line.match.Click+=delegate{Match(line);};
        }
        preview=new TextBox(){Width=1120,Height=117,Multiline=true,ReadOnly=true,ScrollBars=ScrollBars.Vertical};body.Controls.Add(preview);
        var actions=Row(45);generate=new Button(){Text="直接生成到背包",Width=245,Height=35};copy=new Button(){Text="复制生成指令",Width=155,Height=35};
        actions.Controls.Add(generate);actions.Controls.Add(copy);actions.Controls.Add(new Label(){Text="生成需localtest / UID10001进入世界；操作完成前请勿同时手动发放。",AutoSize=true,Margin=new Padding(10,7,0,0)});body.Controls.Add(actions);
        var presetsRow=Row(45);presetsRow.Controls.Add(Caption("配方名"));presetName=new TextBox(){Width=165,Text="我的圣遗物"};presetsRow.Controls.Add(presetName);save=new Button(){Text="保存配方",Width=105,Height=34};presetsRow.Controls.Add(save);presets=Combo(260);presetsRow.Controls.Add(presets);load=new Button(){Text="载入配方",Width=105,Height=34};presetsRow.Controls.Add(load);body.Controls.Add(presetsRow);
        note=new Label(){Width=1120,Height=48,ForeColor=Color.DimGray,Text="标准范围使用真实贡献次数预算；自由测试可以超出预算（并非官服合法装备）。\n离线可预览和保存配方；每次生成新增独立物品，已有装备不变。数值存在游戏浮点与显示四舍五入差异。"};body.Controls.Add(note);Controls.Add(body);
        search.TextChanged+=delegate{FillSets();};sets.SelectedIndexChanged+=delegate{if(!updating)FillSlots();};slots.SelectedIndexChanged+=delegate{if(!updating)FillStars();};stars.SelectedIndexChanged+=delegate{if(!updating)FillInitial();};initial.SelectedIndexChanged+=delegate{if(!updating)LoadPiece();};
        main.SelectedIndexChanged+=delegate{if(!updating){FillSubs(true);UpdatePreview();}};
        level.ValueChanged+=delegate{if(!updating){FillSubs(false);UpdatePreview();}};quantity.ValueChanged+=delegate{if(!updating)UpdatePreview();};mode.SelectedIndexChanged+=delegate{if(!updating)UpdatePreview();};
        copy.Click+=delegate{if(current!=null)Clipboard.SetText("/"+ArtifactMath.Command(current));};generate.Click+=delegate{Generate();};save.Click+=delegate{SavePreset();};load.Click+=delegate{LoadPreset();};
        FillSets();RefreshPresets();
        if(embedded){select.Visible=false;effect.Visible=false;options.Visible=false;actions.Visible=false;presetsRow.Visible=false;}
    }
    static FlowLayoutPanel Row(int height){return new FlowLayoutPanel(){Width=1120,Height=height,WrapContents=false,Margin=new Padding(0),Padding=new Padding(0,3,0,0)};}
    static Label Caption(string s){return new Label(){Text=s,AutoSize=true,Margin=new Padding(0,6,5,0)};}
    static ComboBox Combo(int width){return new ComboBox(){Width=width,DropDownStyle=ComboBoxStyle.DropDownList};}
    static NumericUpDown Number(int min,int max,int value,int width){return new NumericUpDown(){Minimum=min,Maximum=max,Value=value,Width=width};}
    void FillSets(){int old=(sets.SelectedItem as ArtifactSet)==null?15020:((ArtifactSet)sets.SelectedItem).id;updating=true;sets.Items.Clear();foreach(var s in catalog.sets.Where(s=>s.name.IndexOf(search.Text.Trim(),StringComparison.OrdinalIgnoreCase)>=0||s.id.ToString().Contains(search.Text.Trim())))sets.Items.Add(s);sets.SelectedItem=sets.Items.Cast<ArtifactSet>().FirstOrDefault(s=>s.id==old);if(sets.SelectedIndex<0&&sets.Items.Count>0)sets.SelectedIndex=0;updating=false;FillSlots();}
    void FillSlots(){var set=sets.SelectedItem as ArtifactSet;updating=true;slots.Items.Clear();if(set!=null){effect.Text="2件套："+set.twoPiece+"\n4件套："+set.fourPiece;foreach(var slot in new[]{"EQUIP_BRACER","EQUIP_NECKLACE","EQUIP_SHOES","EQUIP_RING","EQUIP_DRESS"}){var p=catalog.pieces.FirstOrDefault(x=>x.setId==set.id&&x.slot==slot);if(p!=null)slots.Items.Add(new SlotChoice(){code=slot,name=p.slotName});}}else effect.Text="没有匹配的套装。";if(slots.Items.Count>0)slots.SelectedIndex=0;updating=false;FillStars();}
    void FillStars(){var s=sets.SelectedItem as ArtifactSet;var slot=slots.SelectedItem as SlotChoice;updating=true;stars.Items.Clear();if(s!=null&&slot!=null)foreach(int n in catalog.pieces.Where(p=>p.setId==s.id&&p.slot==slot.code).Select(p=>p.stars).Distinct().OrderBy(x=>x))stars.Items.Add(n);if(stars.Items.Count>0)stars.SelectedIndex=stars.Items.Count-1;updating=false;FillInitial();}
    void FillInitial(){var s=sets.SelectedItem as ArtifactSet;var slot=slots.SelectedItem as SlotChoice;updating=true;initial.Items.Clear();if(s!=null&&slot!=null&&stars.SelectedItem!=null)foreach(int n in catalog.pieces.Where(p=>p.setId==s.id&&p.slot==slot.code&&p.stars==(int)stars.SelectedItem).Select(p=>p.initial).Distinct().OrderBy(x=>x))initial.Items.Add(n);if(initial.Items.Count>0)initial.SelectedIndex=initial.Items.Count-1;updating=false;LoadPiece();}
    void LoadPiece(){var s=sets.SelectedItem as ArtifactSet;var slot=slots.SelectedItem as SlotChoice;piece=s==null||slot==null||stars.SelectedItem==null||initial.SelectedItem==null?null:catalog.pieces.Where(p=>p.setId==s.id&&p.slot==slot.code&&p.stars==(int)stars.SelectedItem&&p.initial==(int)initial.SelectedItem).OrderByDescending(p=>p.id).FirstOrDefault();updating=true;main.Items.Clear();if(piece!=null){level.Maximum=piece.maxLevel;level.Value=piece.maxLevel;foreach(var m in piece.mains)main.Items.Add(m);string prefer=piece.slot=="EQUIP_SHOES"?"FIGHT_PROP_CHARGE_EFFICIENCY":piece.slot=="EQUIP_RING"?"FIGHT_PROP_FIRE_ADD_HURT":piece.slot=="EQUIP_DRESS"?"FIGHT_PROP_CRITICAL":"";main.SelectedItem=piece.mains.FirstOrDefault(m=>m.prop==prefer);if(main.SelectedIndex<0)main.SelectedIndex=0;}updating=false;FillSubs(false);UpdatePreview();}
    void FillSubs(bool preserve){updating=true;var m=main.SelectedItem as ArtifactMain;var used=new HashSet<string>();var preferred=new[]{"FIGHT_PROP_CRITICAL","FIGHT_PROP_CRITICAL_HURT","FIGHT_PROP_ATTACK_PERCENT","FIGHT_PROP_CHARGE_EFFICIENCY","FIGHT_PROP_ELEMENT_MASTERY","FIGHT_PROP_HP_PERCENT","FIGHT_PROP_DEFENSE_PERCENT","FIGHT_PROP_ATTACK","FIGHT_PROP_HP","FIGHT_PROP_DEFENSE"};int budget=piece==null?0:piece.initial+(int)level.Value/4,n=Math.Min(4,budget);for(int i=0;i<lines.Count;i++){var l=lines[i];string old=l.stat==null?null:l.stat.prop;var choices=piece==null||m==null?new List<ArtifactSub>():piece.subs.Where(x=>x.prop!=m.prop).OrderBy(x=>Array.IndexOf(preferred,x.prop)<0?999:Array.IndexOf(preferred,x.prop)).ToList();l.type.Items.Clear();l.type.Items.Add("—不添加—");foreach(var x in choices)l.type.Items.Add(x);ArtifactSub selected=preserve?choices.FirstOrDefault(x=>x.prop==old&&!used.Contains(x.prop)):null;if(selected==null&&i<n)selected=choices.FirstOrDefault(x=>!used.Contains(x.prop));l.type.SelectedItem=selected;if(selected==null)l.type.SelectedIndex=0;l.stat=selected;if(selected!=null)used.Add(selected.prop);if(!preserve){l.mixed=null;l.tier.SelectedIndex=3;l.count.Value=selected==null?0:1;}else if(selected==null)l.count.Value=0;}if(!preserve&&n>0){int extra=budget-n;lines[0].count.Value+=extra/2;lines[Math.Min(1,n-1)].count.Value+=extra-extra/2;}updating=false;}
    int[] Counts(ArtifactSubLine line){if(line.stat==null)return new int[0];if(line.mixed!=null)return (int[])line.mixed.Clone();var counts=new int[line.stat.rolls.Count];counts[Math.Min(line.tier.SelectedIndex<0?3:line.tier.SelectedIndex,counts.Length-1)]=(int)line.count.Value;return counts;}
    void Match(ArtifactSubLine l){if(l.stat==null||l.count.Value<1){MessageBox.Show("先选副词条并填写至少1次贡献。","目标匹配");return;}try{var counts=ArtifactMath.Nearest(l.stat,(int)l.count.Value,(double)l.target.Value);l.changing=true;l.mixed=counts;l.tier.SelectedIndex=4;l.changing=false;UpdatePreview();double actual=ArtifactMath.Total(l.stat,counts);note.Text="目标匹配实际得到："+ArtifactMath.Display(actual,l.stat.percent)+"；档位贡献："+String.Join(" / ",counts)+"。实际值以预览为准，仍须满足当前模式的总次数预算。";}catch(Exception e){l.changing=false;MessageBox.Show(e.Message,"目标匹配");}}
    ArtifactRequest Build(){if(piece==null||main.SelectedItem==null)throw new Exception("先选择套装、部位和主词条。");var r=new ArtifactRequest(){itemId=piece.id,level=(int)level.Value,mainPropId=((ArtifactMain)main.SelectedItem).id,quantity=(int)quantity.Value,mode=mode.SelectedIndex==0?"standard":"free"};var kinds=new HashSet<string>();foreach(var l in lines){if(l.stat==null)continue;if(!kinds.Add(l.stat.prop))throw new Exception("四条副词条类型应互不重复。");var counts=Counts(l);for(int i=0;i<counts.Length;i++)if(counts[i]>0)r.affixes.Add(new AffixCount(){id=l.stat.rolls[i].id,count=counts[i]});}ArtifactMath.Validate(piece,r);return r;}
    void UpdatePreview(){if(preview==null)return;current=null;try{var m=main.SelectedItem as ArtifactMain;mainValue.Text=m==null?"—":ArtifactMath.Display(m.values[(int)level.Value],m.percent);foreach(var l in lines)l.value.Text=l.stat==null?"—":ArtifactMath.Display(ArtifactMath.Total(l.stat,Counts(l)),l.stat.percent);current=Build();var s=sets.SelectedItem as ArtifactSet;var text=new StringBuilder(s.name+" · "+piece.slotName+"（"+piece.name+"） · "+piece.stars+"★ · +"+current.level+" · ID "+piece.id+"\r\n主词条："+m.label+" "+mainValue.Text+"\r\n");foreach(var l in lines)if(l.stat!=null)text.Append(l.stat.label+" "+l.value.Text+"（"+l.count.Value+"次）  ");text.Append("\r\n模式："+(current.mode=="standard"?"标准范围":"自由测试/超规格")+"；总贡献 "+current.affixes.Sum(x=>x.count)+"；标准预算 "+(piece.initial+current.level/4)+"\r\n/"+ArtifactMath.Command(current));preview.Text=text.ToString();preview.ForeColor=Color.Black;}catch(Exception e){preview.Text="请调整配置："+e.Message;preview.ForeColor=Color.Firebrick;}generate.Enabled=current!=null&&!busy&&!externalBusy;copy.Enabled=current!=null&&!busy&&!externalBusy;save.Enabled=current!=null&&!busy&&!externalBusy;load.Enabled=!busy&&!externalBusy;if(RequestChanged!=null)RequestChanged();}
    void SavePreset(){if(current==null)return;try{string title=presetName.Text.Trim();if(title.Length<1||title.Length>70)throw new Exception("配方名填1–70个字符。");string folder=Path.Combine(root,"presets\\artifacts");Directory.CreateDirectory(folder);string file=Path.Combine(folder,Guid.NewGuid().ToString("N")+".json");File.WriteAllText(file,json.Serialize(new Dictionary<string,object>(){{"title",title},{"data",current}}),new UTF8Encoding(false));RefreshPresets();MessageBox.Show("已保存到E盘，未发放任何物品。","保存配方");}catch(Exception e){MessageBox.Show(e.Message,"保存配方");}}
    void RefreshPresets(){presets.Items.Clear();string folder=Path.Combine(root,"presets\\artifacts");Directory.CreateDirectory(folder);foreach(string file in Directory.GetFiles(folder,"*.json").OrderByDescending(File.GetLastWriteTimeUtc)){try{var d=json.Deserialize<Dictionary<string,object>>(File.ReadAllText(file));presets.Items.Add(new PresetChoice(){file=file,title=Convert.ToString(d["title"])});}catch{}}if(presets.Items.Count>0)presets.SelectedIndex=0;}
    void LoadPreset(){var choice=presets.SelectedItem as PresetChoice;if(choice==null)return;try{var d=json.Deserialize<Dictionary<string,object>>(File.ReadAllText(choice.file));var r=json.Deserialize<ArtifactRequest>(json.Serialize(d["data"]));ApplyRequest(r);presetName.Text=choice.title;}catch(Exception e){updating=false;MessageBox.Show("配方读取问题："+e.Message,"载入配方");}}
    public void ApplyRequest(ArtifactRequest r){var p=catalog.pieces.FirstOrDefault(x=>x.id==r.itemId);ArtifactMath.Validate(p,r);if(search.Text.Length>0)search.Text="";updating=true;sets.SelectedItem=catalog.sets.First(x=>x.id==p.setId);updating=false;FillSlots();updating=true;slots.SelectedItem=slots.Items.Cast<SlotChoice>().First(x=>x.code==p.slot);updating=false;FillStars();updating=true;stars.SelectedItem=p.stars;updating=false;FillInitial();updating=true;initial.SelectedItem=p.initial;updating=false;LoadPiece();updating=true;level.Value=r.level;quantity.Value=r.quantity;mode.SelectedIndex=r.mode=="standard"?0:1;main.SelectedItem=piece.mains.First(x=>x.id==r.mainPropId);updating=false;FillSubs(false);updating=true;foreach(var l in lines){l.type.SelectedIndex=0;l.stat=null;l.count.Value=0;l.mixed=null;}int index=0;foreach(var stat in r.affixes.Select(a=>piece.subs.First(s=>s.rolls.Any(t=>t.id==a.id))).GroupBy(s=>s.prop).Select(g=>g.First())){var cs=stat.rolls.Select(t=>r.affixes.Where(a=>a.id==t.id).Sum(a=>a.count)).ToArray();if(cs.Sum()==0)continue;var l=lines[index++];l.stat=stat;l.type.SelectedItem=l.type.Items.Cast<object>().OfType<ArtifactSub>().First(x=>x.prop==stat.prop);l.count.Value=cs.Sum();l.mixed=cs;l.tier.SelectedIndex=cs.Count(x=>x>0)==1?Array.FindIndex(cs,x=>x>0):4;l.target.Value=Math.Round((decimal)ArtifactMath.Total(stat,cs)*(stat.percent?100:1),2);}updating=false;note.Text="已载入实际词条组合；尚未生成任何物品。";UpdatePreview();}
    void Generate(){if(current==null||busy||externalBusy)return;var request=current;
        string token=Guid.NewGuid().ToString("N"),folder=Path.Combine(root,"run\\artifact-requests");Directory.CreateDirectory(folder);File.WriteAllText(Path.Combine(folder,token+".json"),json.Serialize(request),new UTF8Encoding(false));busy=true;if(BusyChanged!=null)BusyChanged(true);UpdatePreview();note.Text="正在通过服务端生成并核对背包记录，请保持UID10001在线，完成前不要重复操作。";
        var worker=new BackgroundWorker();worker.DoWork+=delegate(object sender,DoWorkEventArgs e){var info=new ProcessStartInfo(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.Windows),"System32\\WindowsPowerShell\\v1.0\\powershell.exe"),"-NoProfile -ExecutionPolicy Bypass -File \""+Path.Combine(root,"scripts\\artifact-control.ps1")+"\" -RequestId "+token){UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true,StandardOutputEncoding=Encoding.UTF8,StandardErrorEncoding=Encoding.UTF8,WorkingDirectory=root};info.EnvironmentVariables["PSModulePath"]=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.Windows),"System32\\WindowsPowerShell\\v1.0\\Modules");using(var p=Process.Start(info)){var o=p.StandardOutput.ReadToEndAsync();var error=p.StandardError.ReadToEndAsync();p.WaitForExit();string text=o.Result+Environment.NewLine+error.Result;File.WriteAllText(Path.Combine(root,"logs\\artifact-ui.log"),text,Encoding.UTF8);if(p.ExitCode!=0)throw new Exception(text.Substring(0,Math.Min(text.Length,1300))+"\n日志："+Path.Combine(root,"logs\\artifact-ui.log"));e.Result=o.Result;}};
        worker.RunWorkerCompleted+=delegate(object sender,RunWorkerCompletedEventArgs e){busy=false;if(BusyChanged!=null)BusyChanged(false);UpdatePreview();if(e.Error!=null){note.Text="本次生成尚未确认，请检查日志/审计记录，先不要重复点击生成。";MessageBox.Show(e.Error.Message,"圣遗物生成问题",MessageBoxButtons.OK,MessageBoxIcon.Warning);}else try{var result=json.Deserialize<ArtifactReceipt>(((string)e.Result).Trim());note.Text="生成完成，已核对存档：新增 "+result.added+" 件。请求记录："+token;}catch(Exception ex){MessageBox.Show("请检查已保存回执："+ex.Message,"回执读取");}worker.Dispose();};worker.RunWorkerAsync();
    }
}
